function solve(nums, k) {
  const n = nums.length;
  if (k <= 0) return 0;
  let count = 0;
  for (let i = 0; i < n; i++) {
    let prod = 1;
    for (let j = i; j < n; j++) {
      if (nums[j] === 0) {
        // this zero keeps the product at 0 for every longer subarray
        count += n - j;
        break;
      }
      if (prod >= k) continue;
      prod *= nums[j];
      if (prod < k) count++;
    }
  }
  return count;
}

function solve(nums, k) {
  if (k <= 0) return 0;
  let left = 0;
  let prod = 1;
  let lastZero = -1;
  let count = 0;
  for (let right = 0; right < nums.length; right++) {
    if (nums[right] === 0) {
      lastZero = right;
      left = right + 1;
      prod = 1;
    } else {
      prod *= nums[right];
      while (left <= right && prod >= k) {
        prod /= nums[left];
        left++;
      }
    }
    count += lastZero + 1;
    if (left <= right) count += right - left + 1;
  }
  return count;
}
